/* ===== header: include/wlr/render/color.h ===== */
/*
 * This an unstable interface of wlroots. No guarantees are made regarding the
 * future consistency of this API.
 */
#ifndef WLR_USE_UNSTABLE
#error "Add -DWLR_USE_UNSTABLE to enable unstable wlroots features"
#endif

#ifndef WLR_RENDER_COLOR_H
#define WLR_RENDER_COLOR_H

#include <stdbool.h>
#include <stdint.h>
#include <sys/types.h>

/**
 * Well-known color primaries.
 */
enum wlr_color_named_primaries {
	WLR_COLOR_NAMED_PRIMARIES_SRGB = 1 << 0,
	WLR_COLOR_NAMED_PRIMARIES_BT2020 = 1 << 1,
};

/**
 * Well-known color transfer functions.
 */
enum wlr_color_transfer_function {
	WLR_COLOR_TRANSFER_FUNCTION_SRGB = 1 << 0,
	WLR_COLOR_TRANSFER_FUNCTION_ST2084_PQ = 1 << 1,
	WLR_COLOR_TRANSFER_FUNCTION_EXT_LINEAR = 1 << 2,
	WLR_COLOR_TRANSFER_FUNCTION_GAMMA22 = 1 << 3,
	WLR_COLOR_TRANSFER_FUNCTION_BT1886 = 1 << 4,
};

/**
 * Specifies alpha blending modes.  Note that premultiplied_electrical
 * is the default, so there is no "none" or "unset" value.
 */
enum wlr_alpha_mode {
	WLR_COLOR_ALPHA_MODE_PREMULTIPLIED_ELECTRICAL,
	WLR_COLOR_ALPHA_MODE_PREMULTIPLIED_OPTICAL,
	WLR_COLOR_ALPHA_MODE_STRAIGHT,
};

/**
 * Well-known color encodings, each representing a set of matrix coefficients
 * used to convert that particular YCbCr encoding to RGB.  NONE means the
 * value is unset or unknown.
 */
enum wlr_color_encoding {
	WLR_COLOR_ENCODING_NONE = 0,
	WLR_COLOR_ENCODING_IDENTITY = 1 << 0,
	WLR_COLOR_ENCODING_BT709 = 1 << 1,
	WLR_COLOR_ENCODING_FCC = 1 << 2,
	WLR_COLOR_ENCODING_BT601 = 1 << 3,
	WLR_COLOR_ENCODING_SMPTE240 = 1 << 4,
	WLR_COLOR_ENCODING_BT2020 = 1 << 5,
	WLR_COLOR_ENCODING_BT2020_CL = 1 << 6,
	WLR_COLOR_ENCODING_ICTCP = 1 << 7,
};

/**
 * Specifies whether a particular color-encoding uses full- or limited-range
 * values.  NONE means the value is unset or unknown.
 */
enum wlr_color_range {
	WLR_COLOR_RANGE_NONE,
	WLR_COLOR_RANGE_LIMITED,
	WLR_COLOR_RANGE_FULL,
};

/**
 * Chroma sample locations, corresponding to Chroma420SampleLocType code
 * points in H.273.  NONE means the value is unset or unknown.
 */
enum wlr_color_chroma_location {
	WLR_COLOR_CHROMA_LOCATION_NONE,
	WLR_COLOR_CHROMA_LOCATION_TYPE0,
	WLR_COLOR_CHROMA_LOCATION_TYPE1,
	WLR_COLOR_CHROMA_LOCATION_TYPE2,
	WLR_COLOR_CHROMA_LOCATION_TYPE3,
	WLR_COLOR_CHROMA_LOCATION_TYPE4,
	WLR_COLOR_CHROMA_LOCATION_TYPE5,
};

/**
 * CIE 1931 xy chromaticity coordinates.
 */
struct wlr_color_cie1931_xy {
	float x, y;
};

/**
 * Color primaries and white point describing a color volume.
 */
struct wlr_color_primaries {
	struct wlr_color_cie1931_xy red, green, blue, white;
};

/**
 * Luminance range and reference white luminance level, in cd/m².
 */
struct wlr_color_luminances {
	float min, max, reference;
};

/**
 * The representation used by a color transform.
 */
enum wlr_color_transform_type {
	WLR_COLOR_TRANSFORM_INVERSE_EOTF,
	WLR_COLOR_TRANSFORM_LCMS2,
	WLR_COLOR_TRANSFORM_LUT_3X1D,
	WLR_COLOR_TRANSFORM_MATRIX,
	WLR_COLOR_TRANSFORM_PIPELINE,
};

/**
 * A color transformation formula, which maps a linear color space with
 * sRGB primaries to an output color space.
 *
 * For ease of use, this type is heap allocated and reference counted.
 * Use wlr_color_transform_ref()/wlr_color_transform_unref(). The initial reference
 * count after creation is 1.
 *
 * Color transforms are immutable; their type/parameters should not be changed,
 * and this API provides no functions to modify them after creation.
 *
 * This formula may be implemented using a 3d look-up table, or some other
 * means. Renderer implementations may inspect the type and the corresponding
 * concrete transform structure below.
 */
struct wlr_color_transform {
	enum wlr_color_transform_type type;

	struct {
		int ref_count;
		struct wlr_addon_set addons; // per-renderer helper state
	} WLR_PRIVATE;
};

struct wlr_color_transform_inverse_eotf {
	struct wlr_color_transform base;

	enum wlr_color_transfer_function tf;
};

/**
 * The formula is approximated via three 1D look-up tables. The flat lut_3x1d
 * array has a length of 3 * dim.
 *
 * The offset of a color value for a given channel and color index is:
 *
 *     offset = channel_index * dim + color_index
 */
struct wlr_color_transform_lut_3x1d {
	struct wlr_color_transform base;

	uint16_t *lut_3x1d;
	size_t dim;
};

struct wlr_color_transform_matrix {
	struct wlr_color_transform base;

	float matrix[9];
};

struct wlr_color_transform_pipeline {
	struct wlr_color_transform base;

	struct wlr_color_transform **transforms;
	size_t len;
};

/**
 * Get a struct wlr_color_transform_inverse_eotf from a generic
 * struct wlr_color_transform. Asserts that the base type is
 * WLR_COLOR_TRANSFORM_INVERSE_EOTF.
 */
struct wlr_color_transform_inverse_eotf *wlr_color_transform_inverse_eotf_from_base(
	struct wlr_color_transform *tr);

/**
 * Get a struct wlr_color_transform_lut_3x1d from a generic
 * struct wlr_color_transform. Asserts that the base type is
 * WLR_COLOR_TRANSFORM_LUT_3X1D.
 */
struct wlr_color_transform_lut_3x1d *wlr_color_transform_lut_3x1d_from_base(
	struct wlr_color_transform *tr);

/**
 * Get a struct wlr_color_transform_matrix from a generic
 * struct wlr_color_transform. Asserts that the base type is
 * WLR_COLOR_TRANSFORM_MATRIX.
 */
struct wlr_color_transform_matrix *wlr_color_transform_matrix_from_base(
	struct wlr_color_transform *tr);

/**
 * Get a struct wlr_color_transform_pipeline from a generic
 * struct wlr_color_transform. Asserts that the base type is
 * WLR_COLOR_TRANSFORM_PIPELINE.
 */
struct wlr_color_transform_pipeline *wlr_color_transform_pipeline_from_base(
	struct wlr_color_transform *tr);

/**
 * Initialize a color transformation to convert linear
 * (with sRGB(?) primaries) to an ICC profile. Returns NULL on failure.
 */
struct wlr_color_transform *wlr_color_transform_init_linear_to_icc(
	const void *data, size_t size);

/**
 * Initialize a color transformation to apply EOTF⁻¹ encoding. Returns
 * NULL on failure.
 */
struct wlr_color_transform *wlr_color_transform_init_linear_to_inverse_eotf(
	enum wlr_color_transfer_function tf);

/**
 * Initialize a color transformation to apply three 1D look-up tables. dim
 * is the number of elements in each individual LUT. Returns NULL on failure.
 */
struct wlr_color_transform *wlr_color_transform_init_lut_3x1d(size_t dim,
	const uint16_t *r, const uint16_t *g, const uint16_t *b);

/**
 * Initialize a color transformation to apply a 3×3 matrix. Returns NULL on
 * failure.
 */
struct wlr_color_transform *wlr_color_transform_init_matrix(const float matrix[static 9]);

/**
 * Initialize a color transformation to apply a sequence of color transforms
 * one after another.
 */
struct wlr_color_transform *wlr_color_transform_init_pipeline(
	struct wlr_color_transform **transforms, size_t len);

/**
 * Increase the reference count of the color transform by 1.
 */
struct wlr_color_transform *wlr_color_transform_ref(struct wlr_color_transform *tr);

/**
 * Reduce the reference count of the color transform by 1; freeing it and
 * all associated resources when the reference count hits zero.
 */
void wlr_color_transform_unref(struct wlr_color_transform *tr);

/**
 * Evaluate a color transform for a given RGB triplet.
 */
void wlr_color_transform_eval(struct wlr_color_transform *tr,
	float out[static 3], const float in[static 3]);

/**
 * Obtain primaries values from a well-known primaries name.
 */
void wlr_color_primaries_from_named(struct wlr_color_primaries *out,
	enum wlr_color_named_primaries named);

/**
 * Compute the matrix to convert between two linear RGB color spaces
 */
void wlr_color_primaries_transform_absolute_colorimetric(
	const struct wlr_color_primaries *source,
	const struct wlr_color_primaries *destination, float matrix[static 9]);

#endif


/* ===== header: include/wlr/util/box.h ===== */
/*
* This is a stable interface of wlroots. Future changes will be limited to:
 *
 * - New functions
 * - New struct members
 * - New enum members
 *
 * Note that wlroots does not make an ABI compatibility promise - in the future,
 * the layout and size of structs used by wlroots may change, requiring code
 * depending on this header to be recompiled (but not edited).
 *
 * Breaking changes are announced in the release notes and follow a 1-year
 * deprecation schedule.
 */
#ifndef WLR_UTIL_BOX_H
#define WLR_UTIL_BOX_H

#include <stdbool.h>
#include <wayland-server-protocol.h>

/**
 * A box representing a rectangle region in a 2D space.
 *
 * The x and y coordinates are inclusive, and the width and height lengths are
 * exclusive. In other words, the box starts from the coordinates (x, y), and
 * goes up to but not including (x + width, y + height).
 */
struct wlr_box {
	int x, y;
	int width, height;
};

/**
 * A floating-point box representing a rectangle region in a 2D space.
 *
 * struct wlr_fbox has the same semantics as struct wlr_box.
 */
struct wlr_fbox {
	double x, y;
	double width, height;
};

/**
 * Functions below accept NULL where a box is expected, which is treated
 * the same as an empty box.
 */

/**
 * Finds the closest point within the box bounds.
 *
 * Returns NAN if the box is empty.
 */
void wlr_box_closest_point(const struct wlr_box *box, double x, double y,
	double *dest_x, double *dest_y);

/**
 * Gives the intersecting box between two struct wlr_box.
 *
 * Returns an empty box if the provided boxes don't intersect.
 */
bool wlr_box_intersection(struct wlr_box *dest, const struct wlr_box *box_a,
	const struct wlr_box *box_b);

/**
 * Gives the minimum bounding box that contains the two boxes.
 *
 * An empty box does not contribute to the bounding box. Returns an empty box if
 * both boxes are empty.
 */
bool wlr_box_bounds(struct wlr_box *dest, const struct wlr_box *box_a,
	const struct wlr_box *box_b);

/**
 * Verifies if a point is contained within the bounds of a given struct wlr_box.
 *
 * For example:
 *
 * - A point at (100, 50) is not contained in the box (0, 0, 100, 50).
 * - A point at (10, 10) is contained in the box (10, 0, 50, 50).
 */
bool wlr_box_contains_point(const struct wlr_box *box, double x, double y);

/**
 * Verifies that a box is fully contained within another box.
 *
 * Returns true if the "smaller" box is fully contained within the "bigger" box.
 * If either of the boxes are empty, false is returned.
 */
bool wlr_box_contains_box(const struct wlr_box *bigger, const struct wlr_box *smaller);

/**
 * Checks whether a box is empty or not.
 *
 * A box is considered empty if its width and/or height is zero or negative.
 */
bool wlr_box_empty(const struct wlr_box *box);

/**
 * Transforms a box inside a (0, 0, width, height) box.
 */
void wlr_box_transform(struct wlr_box *dest, const struct wlr_box *box,
	enum wl_output_transform transform, int width, int height);

/**
 * Checks whether a box is empty or not.
 *
 * A box is considered empty if its width and/or height is zero or negative.
 */
bool wlr_fbox_empty(const struct wlr_fbox *box);

/**
 * Transforms a floating-point box inside a (0, 0, width, height) box.
 */
void wlr_fbox_transform(struct wlr_fbox *dest, const struct wlr_fbox *box,
	enum wl_output_transform transform, double width, double height);

#ifdef WLR_USE_UNSTABLE

/**
 * Checks whether two boxes intersect.
 *
 * Returns false if either box is empty.
 */
bool wlr_box_intersects(const struct wlr_box *a, const struct wlr_box *b);

/**
 * Returns true if the two boxes are equal, false otherwise.
 */
bool wlr_box_equal(const struct wlr_box *a, const struct wlr_box *b);

/**
 * Returns true if the two boxes are equal, false otherwise.
 */
bool wlr_fbox_equal(const struct wlr_fbox *a, const struct wlr_fbox *b);

#endif

#endif


/* ===== header: include/wlr/render/pass.h ===== */
/*
 * This an unstable interface of wlroots. No guarantees are made regarding the
 * future consistency of this API.
 */
#ifndef WLR_USE_UNSTABLE
#error "Add -DWLR_USE_UNSTABLE to enable unstable wlroots features"
#endif

#ifndef WLR_RENDER_PASS_H
#define WLR_RENDER_PASS_H

#include <pixman.h>
#include <stdint.h>
#include <wayland-server-core.h>

struct wlr_renderer;
struct wlr_buffer;

/**
 * A render pass accumulates drawing operations until submitted to the GPU.
 */
struct wlr_render_pass;

/**
 * An object that can be queried after a render to get the duration of the render.
 */
struct wlr_render_timer;

struct wlr_buffer_pass_options {
	/* Timer to measure the duration of the render pass */
	struct wlr_render_timer *timer;
	/* Color transform to apply to the output of the render pass.
	 * Leave NULL to indicate the default transform (Gamma 2.2 encoding for
	 * sRGB monitors) */
	struct wlr_color_transform *color_transform;

	/* Signal a timeline synchronization point when the render pass completes.
	 *
	 * When a compositor provides a signal timeline, the renderer may skip
	 * implicit signal synchronization.
	 *
	 * Support for this feature is advertised by features.timeline in
	 * struct wlr_renderer.
	 */
	struct wlr_drm_syncobj_timeline *signal_timeline;
	uint64_t signal_point;
};

/**
 * Begin a new render pass with the supplied destination buffer.
 *
 * Callers must call wlr_render_pass_submit() once they are done with the
 * render pass.
 */
struct wlr_render_pass *wlr_renderer_begin_buffer_pass(struct wlr_renderer *renderer,
	struct wlr_buffer *buffer, const struct wlr_buffer_pass_options *options);

/**
 * Submit the render pass.
 *
 * The render pass cannot be used after this function is called.
 */
bool wlr_render_pass_submit(struct wlr_render_pass *render_pass);

/**
 * Blend modes.
 */
enum wlr_render_blend_mode {
	/* Pre-multiplied alpha (default) */
	WLR_RENDER_BLEND_MODE_PREMULTIPLIED,
	/* Blending is disabled */
	WLR_RENDER_BLEND_MODE_NONE,
};

/**
 * Filter modes.
 */
enum wlr_scale_filter_mode {
	/* bilinear texture filtering (default) */
	WLR_SCALE_FILTER_BILINEAR,
	/* nearest texture filtering */
	WLR_SCALE_FILTER_NEAREST,
};

struct wlr_render_texture_options {
	/* Source texture */
	struct wlr_texture *texture;
	/* Source coordinates, leave empty to render the whole texture */
	struct wlr_fbox src_box;
	/* Destination coordinates, width/height default to the texture size */
	struct wlr_box dst_box;
	/* Opacity between 0 (transparent) and 1 (opaque), leave NULL for opaque */
	const float *alpha;
	/* Clip region, leave NULL to disable clipping */
	const pixman_region32_t *clip;
	/* Transform applied to the source texture */
	enum wl_output_transform transform;
	/* Filtering */
	enum wlr_scale_filter_mode filter_mode;
	/* Blend mode */
	enum wlr_render_blend_mode blend_mode;
	/* Transfer function the source texture is encoded with */
	enum wlr_color_transfer_function transfer_function;
	/* Primaries describing the color volume of the source texture */
	const struct wlr_color_primaries *primaries;
	/* Color encoding of the source texture for YCbCr conversion to RGB */
	enum wlr_color_encoding color_encoding;
	/* Color range of the source texture */
	enum wlr_color_range color_range;
	/* Default: 1.0 */
	const float *luminance_multiplier;

	/* Wait for a timeline synchronization point before texturing.
	 *
	 * When a compositor provides a wait timeline, the renderer may skip
	 * implicit wait synchronization.
	 *
	 * Support for this feature is advertised by features.timeline in
	 * struct wlr_renderer.
	 */
	struct wlr_drm_syncobj_timeline *wait_timeline;
	uint64_t wait_point;
};

/**
 * Render a texture.
 */
void wlr_render_pass_add_texture(struct wlr_render_pass *render_pass,
	const struct wlr_render_texture_options *options);

/**
 * A color value.
 *
 * Each channel has values between 0 and 1 inclusive. The R, G, B
 * channels need to be pre-multiplied by A.
 */
struct wlr_render_color {
	float r, g, b, a;
};

struct wlr_render_rect_options {
	/* Rectangle coordinates */
	struct wlr_box box;
	/* Source color */
	struct wlr_render_color color;
	/* Clip region, leave NULL to disable clipping */
	const pixman_region32_t *clip;
	/* Blend mode */
	enum wlr_render_blend_mode blend_mode;
};

/**
 * Render a rectangle.
 */
void wlr_render_pass_add_rect(struct wlr_render_pass *render_pass,
	const struct wlr_render_rect_options *options);

#endif


/* ===== header: include/wlr/render/dmabuf.h ===== */
/*
 * This an unstable interface of wlroots. No guarantees are made regarding the
 * future consistency of this API.
 */
#ifndef WLR_USE_UNSTABLE
#error "Add -DWLR_USE_UNSTABLE to enable unstable wlroots features"
#endif

#ifndef WLR_RENDER_DMABUF_H
#define WLR_RENDER_DMABUF_H

#include <stdbool.h>
#include <stdint.h>

#define WLR_DMABUF_MAX_PLANES 4

/**
 * A Linux DMA-BUF pixel buffer.
 *
 * If the buffer was allocated with explicit modifiers enabled, the `modifier`
 * field must not be INVALID.
 *
 * If the buffer was allocated with explicit modifiers disabled (either because
 * the driver doesn't support it, or because the user didn't specify a valid
 * modifier list), the `modifier` field can have two values: INVALID means that
 * an implicit vendor-defined modifier is in use, LINEAR means that the buffer
 * is linear. The `modifier` field must not have any other value.
 *
 * When importing a DMA-BUF, users must not ignore the modifier unless it's
 * INVALID or LINEAR. In particular, users must not import a DMA-BUF to a
 * legacy API which doesn't support specifying an explicit modifier unless the
 * modifier is set to INVALID or LINEAR.
 */
struct wlr_dmabuf_attributes {
	int32_t width, height;
	uint32_t format; // FourCC code, see DRM_FORMAT_* in <drm_fourcc.h>
	uint64_t modifier; // see DRM_FORMAT_MOD_* in <drm_fourcc.h>

	int n_planes;
	uint32_t offset[WLR_DMABUF_MAX_PLANES];
	uint32_t stride[WLR_DMABUF_MAX_PLANES];
	int fd[WLR_DMABUF_MAX_PLANES];
};

/**
 * Closes all file descriptors in the DMA-BUF attributes.
 */
void wlr_dmabuf_attributes_finish(struct wlr_dmabuf_attributes *attribs);
/**
 * Clones the DMA-BUF attributes.
 */
bool wlr_dmabuf_attributes_copy(struct wlr_dmabuf_attributes *dst,
	const struct wlr_dmabuf_attributes *src);

#endif


/* ===== header: include/wlr/render/wlr_texture.h ===== */
/*
 * This an unstable interface of wlroots. No guarantees are made regarding the
 * future consistency of this API.
 */
#ifndef WLR_USE_UNSTABLE
#error "Add -DWLR_USE_UNSTABLE to enable unstable wlroots features"
#endif

#ifndef WLR_RENDER_WLR_TEXTURE_H
#define WLR_RENDER_WLR_TEXTURE_H

#include <pixman.h>
#include <stdint.h>
#include <wayland-server-core.h>

struct wlr_buffer;
struct wlr_renderer;
struct wlr_texture_impl;

struct wlr_texture {
	const struct wlr_texture_impl *impl;
	uint32_t width, height;

	struct wlr_renderer *renderer;
};

struct wlr_texture_read_pixels_options {
	/** Memory location to read pixels into */
	void *data;
	/** Format used for writing the pixel data */
	uint32_t format;
	/** Stride in bytes for the data */
	uint32_t stride;
	/** Destination offsets */
	uint32_t dst_x, dst_y;
	/** Source box of the texture to read from. If empty, the full texture is assumed. */
	const struct wlr_box src_box;
	struct wlr_drm_syncobj_timeline *wait_timeline;
	uint64_t wait_point;
};

bool wlr_texture_read_pixels(struct wlr_texture *texture,
	const struct wlr_texture_read_pixels_options *options);

uint32_t wlr_texture_preferred_read_format(struct wlr_texture *texture);

/**
 * Create a new texture from raw pixel data. `stride` is in bytes. The returned
 * texture is mutable.
 */
struct wlr_texture *wlr_texture_from_pixels(struct wlr_renderer *renderer,
	uint32_t fmt, uint32_t stride, uint32_t width, uint32_t height,
	const void *data);

/**
 * Create a new texture from a DMA-BUF. The returned texture is immutable.
 */
struct wlr_texture *wlr_texture_from_dmabuf(struct wlr_renderer *renderer,
	struct wlr_dmabuf_attributes *attribs);

/**
  * Update a texture with a struct wlr_buffer's contents.
  *
  * The update might be rejected (in case the texture is immutable, the buffer
  * has an unsupported type/format, etc), so callers must be prepared to fall
  * back to re-creating the texture from scratch via wlr_texture_from_buffer().
  *
  * The damage can be used by the renderer as an optimization: only the supplied
  * region needs to be updated.
  */
bool wlr_texture_update_from_buffer(struct wlr_texture *texture,
	struct wlr_buffer *buffer, const pixman_region32_t *damage);

/**
 * Destroys the texture.
 */
void wlr_texture_destroy(struct wlr_texture *texture);

/**
 * Create a new texture from a buffer.
 */
struct wlr_texture *wlr_texture_from_buffer(struct wlr_renderer *renderer,
	struct wlr_buffer *buffer);

#endif


/* ===== header: include/wlr/render/wlr_renderer.h ===== */
/*
 * This an unstable interface of wlroots. No guarantees are made regarding the
 * future consistency of this API.
 */
#ifndef WLR_USE_UNSTABLE
#error "Add -DWLR_USE_UNSTABLE to enable unstable wlroots features"
#endif

#ifndef WLR_RENDER_WLR_RENDERER_H
#define WLR_RENDER_WLR_RENDERER_H

#include <stdint.h>
#include <wayland-server-core.h>

struct wlr_backend;
struct wlr_renderer_impl;
struct wlr_drm_format_set;
struct wlr_buffer;
struct wlr_box;
struct wlr_fbox;

/**
 * A renderer for basic 2D operations.
 */
struct wlr_renderer {
	// Capabilities required for the buffer used as a render target (bitmask of
	// enum wlr_buffer_cap)
	uint32_t render_buffer_caps;
	// Supported color encodings for YCbCr textures
	uint32_t color_encodings; // bitmask of enum wlr_color_encoding

	struct {
		struct wl_signal destroy;
		/**
		 * Emitted when the GPU is lost, e.g. on GPU reset.
		 *
		 * Compositors should destroy the renderer and re-create it.
		 */
		struct wl_signal lost;
	} events;

	struct {
		/**
		 * Whether color transforms are supported for input textures
		 */
		bool input_color_transform;
		/**
		 * Does the renderer support color transforms on its output?
		 */
		bool output_color_transform;
		/**
		 * Whether wait/signal timelines are supported.
		 *
		 * See struct wlr_drm_syncobj_timeline.
		 */
		bool timeline;
	} features;

	struct {
		const struct wlr_renderer_impl *impl;
	} WLR_PRIVATE;
};

/**
 * Automatically create a new renderer.
 *
 * Selects an appropriate renderer type to use depending on the backend,
 * platform, environment, etc.
 */
struct wlr_renderer *wlr_renderer_autocreate(struct wlr_backend *backend);

/**
 * Get the formats supporting sampling usage.
 *
 * The buffer capabilities must be passed in.
 *
 * Buffers allocated with a format from this list may be passed to
 * wlr_texture_from_buffer().
 */
const struct wlr_drm_format_set *wlr_renderer_get_texture_formats(
	struct wlr_renderer *r, uint32_t buffer_caps);

/**
 * Initializes wl_shm, linux-dmabuf and other buffer factory protocols.
 *
 * Returns false on failure.
 */
bool wlr_renderer_init_wl_display(struct wlr_renderer *r,
	struct wl_display *wl_display);

/**
 * Initializes wl_shm on the provided struct wl_display.
 */
bool wlr_renderer_init_wl_shm(struct wlr_renderer *r,
	struct wl_display *wl_display);

/**
 * Obtains the FD of the DRM device used for rendering, or -1 if unavailable.
 *
 * The caller doesn't have ownership of the FD, it must not close it.
 */
int wlr_renderer_get_drm_fd(struct wlr_renderer *r);

/**
 * Destroys the renderer.
 *
 * Textures must be destroyed separately.
 */
void wlr_renderer_destroy(struct wlr_renderer *renderer);

/**
 * Allocate and initialise a new render timer.
 */
struct wlr_render_timer *wlr_render_timer_create(struct wlr_renderer *renderer);

/**
 * Get the render duration in nanoseconds from the timer.
 *
 * Returns -1 if the duration is unavailable.
 */
int wlr_render_timer_get_duration_ns(struct wlr_render_timer *timer);

/**
 * Destroy the render timer.
 */
void wlr_render_timer_destroy(struct wlr_render_timer *timer);

#endif


/* ===== header: include/wlr/types/wlr_buffer.h ===== */
/*
 * This an unstable interface of wlroots. No guarantees are made regarding the
 * future consistency of this API.
 */
#ifndef WLR_USE_UNSTABLE
#error "Add -DWLR_USE_UNSTABLE to enable unstable wlroots features"
#endif

#ifndef WLR_TYPES_WLR_BUFFER_H
#define WLR_TYPES_WLR_BUFFER_H

#include <pixman.h>
#include <wayland-server-core.h>

struct wlr_buffer;
struct wlr_renderer;

/**
 * Shared-memory attributes for a buffer.
 */
struct wlr_shm_attributes {
	int fd;
	uint32_t format; // FourCC code, see DRM_FORMAT_* in <drm_fourcc.h>
	int width, height;
	int stride; // Number of bytes between consecutive pixel lines
	off_t offset; // Offset in bytes of the first pixel in FD
};

/**
 * Buffer capabilities.
 *
 * These bits indicate the features supported by a struct wlr_buffer. There is
 * one bit per function in struct wlr_buffer_impl.
 */
enum wlr_buffer_cap {
	WLR_BUFFER_CAP_DATA_PTR = 1 << 0,
	WLR_BUFFER_CAP_DMABUF = 1 << 1,
	WLR_BUFFER_CAP_SHM = 1 << 2,
};

/**
 * A buffer containing pixel data.
 *
 * A buffer has a single producer (the party who created the buffer) and
 * multiple consumers (parties reading the buffer). When all consumers are done
 * with the buffer, it gets released and can be re-used by the producer. When
 * the producer and all consumers are done with the buffer, it gets destroyed.
 */
struct wlr_buffer {
	const struct wlr_buffer_impl *impl;

	int width, height;

	bool dropped;
	size_t n_locks;
	bool accessing_data_ptr;

	struct {
		struct wl_signal destroy;
		struct wl_signal release;
	} events;

	struct wlr_addon_set addons;
};

/**
 * Unreference the buffer. This function should be called by producers when
 * they are done with the buffer.
 */
void wlr_buffer_drop(struct wlr_buffer *buffer);
/**
 * Lock the buffer. This function should be called by consumers to make
 * sure the buffer can be safely read from. Once the consumer is done with the
 * buffer, they should call wlr_buffer_unlock().
 */
struct wlr_buffer *wlr_buffer_lock(struct wlr_buffer *buffer);
/**
 * Unlock the buffer. This function should be called by consumers once they are
 * done with the buffer.
 */
void wlr_buffer_unlock(struct wlr_buffer *buffer);
/**
 * Reads the DMA-BUF attributes of the buffer. If this buffer isn't a DMA-BUF,
 * returns false.
 *
 * The returned DMA-BUF attributes are valid for the lifetime of the
 * struct wlr_buffer. The caller isn't responsible for cleaning up the DMA-BUF
 * attributes.
 */
bool wlr_buffer_get_dmabuf(struct wlr_buffer *buffer,
	struct wlr_dmabuf_attributes *attribs);
/**
 * Read shared memory attributes of the buffer. If this buffer isn't shared
 * memory, returns false.
 *
 * The returned shared memory attributes are valid for the lifetime of the
 * struct wlr_buffer. The caller isn't responsible for cleaning up the shared
 * memory attributes.
 */
bool wlr_buffer_get_shm(struct wlr_buffer *buffer,
	struct wlr_shm_attributes *attribs);
/**
 * Transforms a struct wl_resource into a struct wlr_buffer and locks it. Once
 * the caller is done with the buffer, they must call wlr_buffer_unlock().
 *
 * The provided struct wl_resource must be a wl_buffer.
 */
struct wlr_buffer *wlr_buffer_try_from_resource(struct wl_resource *resource);

/**
 * Check whether a buffer is fully opaque.
 *
 * When true is returned, the buffer is guaranteed to be fully opaque, but the
 * reverse is not true: false may be returned in cases where the buffer is fully
 * opaque.
 */
bool wlr_buffer_is_opaque(struct wlr_buffer *buffer);

/**
 * Buffer data pointer access flags.
 */
enum wlr_buffer_data_ptr_access_flag {
	/**
	 * The buffer contents can be read back.
	 */
	WLR_BUFFER_DATA_PTR_ACCESS_READ = 1 << 0,
	/**
	 * The buffer contents can be written to.
	 */
	WLR_BUFFER_DATA_PTR_ACCESS_WRITE = 1 << 1,
};

/**
 * Get a pointer to a region of memory referring to the buffer's underlying
 * storage. The format and stride can be used to interpret the memory region
 * contents.
 *
 * The returned pointer should be pointing to a valid memory region for the
 * operations specified in the flags. The returned pointer is only valid up to
 * the next wlr_buffer_end_data_ptr_access() call.
 */
bool wlr_buffer_begin_data_ptr_access(struct wlr_buffer *buffer, uint32_t flags,
	void **data, uint32_t *format, size_t *stride);
/**
 * Indicate that a pointer to a buffer's underlying memory will no longer be
 * used.
 *
 * This function must be called after wlr_buffer_begin_data_ptr_access().
 */
void wlr_buffer_end_data_ptr_access(struct wlr_buffer *buffer);

/**
 * A client buffer.
 */
struct wlr_client_buffer {
	struct wlr_buffer base;

	/**
	 * The buffer's texture, if any. A buffer will not have a texture if the
	 * client destroys the buffer before it has been released.
	 */
	struct wlr_texture *texture;
	/**
	 * The buffer this client buffer was created from. NULL if destroyed.
	 */
	struct wlr_buffer *source;

	struct {
		struct wl_listener source_destroy;
		struct wl_listener renderer_destroy;

		size_t n_ignore_locks;
	} WLR_PRIVATE;
};

/**
 * Get a client buffer from a generic buffer. If the buffer isn't a client
 * buffer, returns NULL.
 */
struct wlr_client_buffer *wlr_client_buffer_get(struct wlr_buffer *buffer);

/**
 * A single-pixel buffer.  Used by clients to draw solid-color rectangles.
 */
struct wlr_single_pixel_buffer_v1 {
	struct wlr_buffer base;

	// Full-scale for each component is UINT32_MAX
	uint32_t r, g, b, a;

	struct {
		struct wl_resource *resource;
		struct wl_listener release;

		// Packed little-endian DRM_FORMAT_ARGB8888. Used for data_ptr_access
		uint8_t argb8888[4];
	} WLR_PRIVATE;
};

/**
 * If the wlr_buffer is a wlr_single_pixel_buffer_v1 then unwrap it.
 * Otherwise, returns NULL.
 */
struct wlr_single_pixel_buffer_v1 *wlr_single_pixel_buffer_v1_try_from_buffer(
	struct wlr_buffer *buffer);

#endif


/* ===== header: include/wlr/types/wlr_output.h ===== */
/*
 * This an unstable interface of wlroots. No guarantees are made regarding the
 * future consistency of this API.
 */
#ifndef WLR_USE_UNSTABLE
#error "Add -DWLR_USE_UNSTABLE to enable unstable wlroots features"
#endif

#ifndef WLR_TYPES_WLR_OUTPUT_H
#define WLR_TYPES_WLR_OUTPUT_H

#include <pixman.h>
#include <stdbool.h>
#include <time.h>
#include <wayland-server-protocol.h>
#include <wayland-util.h>

enum wlr_output_mode_aspect_ratio {
	WLR_OUTPUT_MODE_ASPECT_RATIO_NONE,
	WLR_OUTPUT_MODE_ASPECT_RATIO_4_3,
	WLR_OUTPUT_MODE_ASPECT_RATIO_16_9,
	WLR_OUTPUT_MODE_ASPECT_RATIO_64_27,
	WLR_OUTPUT_MODE_ASPECT_RATIO_256_135,
};

struct wlr_output_mode {
	int32_t width, height;
	int32_t refresh; // mHz
	bool preferred;
	enum wlr_output_mode_aspect_ratio picture_aspect_ratio;
	struct wl_list link;
};

struct wlr_output_cursor {
	struct wlr_output *output;
	double x, y;
	bool enabled;
	bool visible;
	uint32_t width, height;
	struct wlr_fbox src_box;
	enum wl_output_transform transform;
	int32_t hotspot_x, hotspot_y;
	struct wlr_texture *texture;
	bool own_texture;
	struct wlr_drm_syncobj_timeline *wait_timeline;
	uint64_t wait_point;
	struct wl_list link;

	struct {
		struct wl_listener renderer_destroy;
		struct wlr_color_transform *color_transform;
	} WLR_PRIVATE;
};

enum wlr_output_adaptive_sync_status {
	WLR_OUTPUT_ADAPTIVE_SYNC_DISABLED,
	WLR_OUTPUT_ADAPTIVE_SYNC_ENABLED,
};

enum wlr_output_state_field {
	WLR_OUTPUT_STATE_BUFFER = 1 << 0,
	WLR_OUTPUT_STATE_DAMAGE = 1 << 1,
	WLR_OUTPUT_STATE_MODE = 1 << 2,
	WLR_OUTPUT_STATE_ENABLED = 1 << 3,
	WLR_OUTPUT_STATE_SCALE = 1 << 4,
	WLR_OUTPUT_STATE_TRANSFORM = 1 << 5,
	WLR_OUTPUT_STATE_ADAPTIVE_SYNC_ENABLED = 1 << 6,
	WLR_OUTPUT_STATE_RENDER_FORMAT = 1 << 7,
	WLR_OUTPUT_STATE_SUBPIXEL = 1 << 8,
	WLR_OUTPUT_STATE_LAYERS = 1 << 9,
	WLR_OUTPUT_STATE_WAIT_TIMELINE = 1 << 10,
	WLR_OUTPUT_STATE_SIGNAL_TIMELINE = 1 << 11,
	WLR_OUTPUT_STATE_COLOR_TRANSFORM = 1 << 12,
	WLR_OUTPUT_STATE_IMAGE_DESCRIPTION = 1 << 13,
	WLR_OUTPUT_STATE_COLOR_REPRESENTATION = 1 << 14,
};

enum wlr_output_state_mode_type {
	WLR_OUTPUT_STATE_MODE_FIXED,
	WLR_OUTPUT_STATE_MODE_CUSTOM,
};

/**
 * Colorimetric image description.
 *
 * Carries information about the color encoding used for a struct wlr_buffer.
 *
 * Supported primaries are advertised in wlr_output.supported_primaries.
 * Supported transfer functions are advertised in
 * wlr_output.supported_transfer_functions.
 *
 * mastering_display_primaries, mastering_luminance, max_cll and max_fall are
 * optional. Luminances are given in cd/m².
 */
struct wlr_output_image_description {
	enum wlr_color_named_primaries primaries;
	enum wlr_color_transfer_function transfer_function;

	struct wlr_color_primaries mastering_display_primaries;
	struct {
		double min, max;
	} mastering_luminance;
	double max_cll; // max content light level
	double max_fall; // max frame-average light level
};

/**
 * Holds the double-buffered output state.
 */
struct wlr_output_state {
	uint32_t committed; // enum wlr_output_state_field
	// Set to true to allow output reconfiguration to occur which may result
	// in temporary output disruptions and content misrepresentations.
	bool allow_reconfiguration;
	pixman_region32_t damage; // output-buffer-local coordinates
	bool enabled;
	float scale;
	enum wl_output_transform transform;
	bool adaptive_sync_enabled;
	uint32_t render_format;
	enum wl_output_subpixel subpixel;

	struct wlr_buffer *buffer;
	// Source crop for the buffer.  If all zeros then no crop is applied.
	// As usual with source crop, this is in buffer coordinates.
	// Double-buffered by WLR_OUTPUT_STATE_BUFFER along with `buffer`.
	struct wlr_fbox buffer_src_box;
	// Destination rect to scale the buffer to (after source crop).  If width
	// and height are zero then the buffer is displayed at native size.  The
	// offset is relative to the origin of this output. Double-buffered by
	// WLR_OUTPUT_STATE_BUFFER along with `buffer`.
	struct wlr_box buffer_dst_box;

	/* Request a tearing page-flip. When enabled, this may cause the output to
	 * display a part of the previous buffer and a part of the current buffer at
	 * the same time. The backend may reject the commit if a tearing page-flip
	 * cannot be performed, in which case the caller should fall back to a
	 * regular page-flip at the next wlr_output.frame event. */
	bool tearing_page_flip;

	// Set if (committed & WLR_OUTPUT_STATE_COLOR_REPRESENTATION)
	enum wlr_color_encoding color_encoding;
	enum wlr_color_range color_range;

	enum wlr_output_state_mode_type mode_type;
	struct wlr_output_mode *mode;
	struct {
		int32_t width, height;
		int32_t refresh; // mHz, may be zero
	} custom_mode;

	struct wlr_output_layer_state *layers;
	size_t layers_len;

	struct wlr_drm_syncobj_timeline *wait_timeline;
	uint64_t wait_point;
	struct wlr_drm_syncobj_timeline *signal_timeline;
	uint64_t signal_point;

	struct wlr_color_transform *color_transform;

	struct wlr_output_image_description *image_description;
};

struct wlr_output_impl;
struct wlr_render_pass;

/**
 * A compositor output region. This typically corresponds to a monitor that
 * displays part of the compositor space.
 *
 * The `frame` event will be emitted when it is a good time for the compositor
 * to submit a new frame.
 *
 * To render a new frame compositors should call wlr_output_begin_render_pass(),
 * perform rendering on that render pass, and finally call
 * wlr_output_commit_state().
 */
struct wlr_output {
	const struct wlr_output_impl *impl;
	struct wlr_backend *backend;
	struct wl_event_loop *event_loop;

	struct wl_global *global;
	struct wl_list resources;

	char *name;
	char *description; // may be NULL
	char *make, *model, *serial; // may be NULL
	int32_t phys_width, phys_height; // mm
	const struct wlr_color_primaries *default_primaries; // may be NULL

	// Note: some backends may have zero modes
	struct wl_list modes; // wlr_output_mode.link
	struct wlr_output_mode *current_mode;
	int32_t width, height;
	int32_t refresh; // mHz, may be zero

	uint32_t supported_primaries; // bitfield of enum wlr_color_named_primaries
	uint32_t supported_transfer_functions; // bitfield of enum wlr_color_transfer_function

	bool enabled;
	float scale;
	enum wl_output_subpixel subpixel;
	enum wl_output_transform transform;
	enum wlr_output_adaptive_sync_status adaptive_sync_status;
	uint32_t render_format;
	enum wlr_color_encoding color_encoding;
	enum wlr_color_range color_range;
	const struct wlr_output_image_description *image_description;

	// Indicates whether making changes to adaptive sync status is supported.
	// If false, changes to adaptive sync status is guaranteed to fail. If
	// true, changes may either succeed or fail.
	bool adaptive_sync_supported;

	bool needs_frame;
	// damage for cursors and fullscreen surface, in output-local coordinates
	bool frame_pending;

	// true for example with VR headsets
	bool non_desktop;

	// Commit sequence number. Incremented on each commit, may overflow.
	uint32_t commit_seq;

	struct {
		// Request to render a frame
		struct wl_signal frame;
		// Emitted when software cursors or backend-specific logic damage the
		// output
		struct wl_signal damage; // struct wlr_output_event_damage
		// Emitted when a new frame needs to be committed (because of
		// backend-specific logic)
		struct wl_signal needs_frame;
		// Emitted right before commit
		struct wl_signal precommit; // struct wlr_output_event_precommit
		// Emitted right after commit
		struct wl_signal commit; // struct wlr_output_event_commit
		// Emitted right after a commit has been presented to the user for
		// enabled outputs
		struct wl_signal present; // struct wlr_output_event_present
		// Emitted after a client bound the wl_output global
		struct wl_signal bind; // struct wlr_output_event_bind
		struct wl_signal description;
		struct wl_signal request_state; // struct wlr_output_event_request_state
		struct wl_signal destroy;
	} events;

	struct wl_event_source *idle_frame;
	struct wl_event_source *idle_done;

	int attach_render_locks; // number of locks forcing rendering

	struct wl_list cursors; // wlr_output_cursor.link
	struct wlr_output_cursor *hardware_cursor;
	struct wlr_swapchain *cursor_swapchain;
	struct wlr_buffer *cursor_front_buffer;
	int software_cursor_locks; // number of locks forcing software cursors

	struct wl_list layers; // wlr_output_layer.link

	struct wlr_allocator *allocator;
	struct wlr_renderer *renderer;
	struct wlr_swapchain *swapchain;

	struct wlr_addon_set addons;

	void *data;

	struct {
		struct wl_listener display_destroy;
		struct wlr_output_image_description image_description_value;
		struct wlr_color_transform *color_transform;
		struct wlr_color_primaries default_primaries_value;
	} WLR_PRIVATE;
};

struct wlr_output_event_damage {
	struct wlr_output *output;
	const pixman_region32_t *damage; // output-buffer-local coordinates
};

struct wlr_output_event_precommit {
	struct wlr_output *output;
	struct timespec when;
	const struct wlr_output_state *state;
};

struct wlr_output_event_commit {
	struct wlr_output *output;
	struct timespec when;
	const struct wlr_output_state *state;
};

enum wlr_output_present_flag {
	// The presentation was synchronized to the "vertical retrace" by the
	// display hardware such that tearing does not happen.
	WLR_OUTPUT_PRESENT_VSYNC = 0x1,
	// The display hardware provided measurements that the hardware driver
	// converted into a presentation timestamp.
	WLR_OUTPUT_PRESENT_HW_CLOCK = 0x2,
	// The display hardware signalled that it started using the new image
	// content.
	WLR_OUTPUT_PRESENT_HW_COMPLETION = 0x4,
	// The presentation of this update was done zero-copy.
	WLR_OUTPUT_PRESENT_ZERO_COPY = 0x8,
};

struct wlr_output_event_present {
	struct wlr_output *output;
	// Frame submission for which this presentation event is for (see
	// wlr_output.commit_seq).
	uint32_t commit_seq;
	// Whether the frame was presented at all.
	bool presented;
	// Time when the content update turned into light the first time.
	struct timespec when;
	// Vertical retrace counter. Zero if unavailable.
	unsigned seq;
	// Prediction of how many nanoseconds after `when` the very next output
	// refresh may occur. Zero if unknown.
	int refresh; // nsec
	uint32_t flags; // enum wlr_output_present_flag
};

struct wlr_output_event_bind {
	struct wlr_output *output;
	struct wl_resource *resource;
};

struct wlr_output_event_request_state {
	struct wlr_output *output;
	const struct wlr_output_state *state;
};

void wlr_output_create_global(struct wlr_output *output, struct wl_display *display);
void wlr_output_destroy_global(struct wlr_output *output);
/**
 * Initialize the output's rendering subsystem with the provided allocator and
 * renderer. After initialization, this function may invoked again to reinitialize
 * the allocator and renderer to different values.
 *
 * Call this function prior to any call to wlr_output_begin_render_pass(),
 * wlr_output_commit_state() or wlr_output_cursor_create().
 *
 * The buffer capabilities of the provided must match the capabilities of the
 * output's backend. Returns false otherwise.
 */
bool wlr_output_init_render(struct wlr_output *output,
	struct wlr_allocator *allocator, struct wlr_renderer *renderer);
/**
 * Returns the preferred mode for this output. If the output doesn't support
 * modes, returns NULL.
 */
struct wlr_output_mode *wlr_output_preferred_mode(struct wlr_output *output);
/**
 * Set the output name.
 *
 * Output names are subject to the following rules:
 *
 * - Each output name must be unique.
 * - The name cannot change after the output has been advertised to clients.
 *
 * For more details, see the protocol documentation for wl_output.name.
 */
void wlr_output_set_name(struct wlr_output *output, const char *name);
void wlr_output_set_description(struct wlr_output *output, const char *desc);
/**
 * Schedule a done event.
 *
 * This is intended to be used by wl_output add-on interfaces.
 */
void wlr_output_schedule_done(struct wlr_output *output);
void wlr_output_destroy(struct wlr_output *output);
/**
 * Computes the transformed output resolution.
 */
void wlr_output_transformed_resolution(struct wlr_output *output,
	int *width, int *height);
/**
 * Computes the transformed and scaled output resolution.
 */
void wlr_output_effective_resolution(struct wlr_output *output,
	int *width, int *height);
/**
 * Test whether this output state would be accepted by the backend. If this
 * function returns true, wlr_output_commit_state() will only fail due to a
 * runtime error. This function does not change the current state of the
 * output.
 */
bool wlr_output_test_state(struct wlr_output *output,
	const struct wlr_output_state *state);
/**
 * Attempts to apply the state to this output. This function may fail for any
 * reason and return false. If failed, none of the state would have been applied,
 * this function is atomic. If the commit succeeded, true is returned.
 *
 * Note: wlr_output_state_finish() would typically be called after the state
 * has been committed.
 */
bool wlr_output_commit_state(struct wlr_output *output,
	const struct wlr_output_state *state);
/**
 * Manually schedules a `frame` event. If a `frame` event is already pending,
 * it is a no-op.
 */
void wlr_output_schedule_frame(struct wlr_output *output);
/**
 * Returns the maximum length of each gamma ramp, or 0 if unsupported.
 */
size_t wlr_output_get_gamma_size(struct wlr_output *output);
/**
 * Returns the wlr_output matching the provided wl_output resource. If the
 * resource isn't a wl_output, it aborts. If the resource is inert (because the
 * wlr_output has been destroyed), NULL is returned.
 */
struct wlr_output *wlr_output_from_resource(struct wl_resource *resource);
/**
 * Locks the output to only use rendering instead of direct scan-out. This is
 * useful if direct scan-out needs to be temporarily disabled (e.g. during
 * screen capture). There must be as many unlocks as there have been locks to
 * restore the original state. There should never be an unlock before a lock.
 */
void wlr_output_lock_attach_render(struct wlr_output *output, bool lock);
/**
 * Locks the output to only use software cursors instead of hardware cursors.
 * This is useful if hardware cursors need to be temporarily disabled (e.g.
 * during screen capture). There must be as many unlocks as there have been
 * locks to restore the original state. There should never be an unlock before
 * a lock.
 */
void wlr_output_lock_software_cursors(struct wlr_output *output, bool lock);
/**
 * Render software cursors. The damage is in buffer-local coordinate space.
 *
 * This is a utility function that can be called when compositors render.
 */
void wlr_output_add_software_cursors_to_render_pass(struct wlr_output *output,
	struct wlr_render_pass *render_pass, const pixman_region32_t *damage);
/**
 * Get the set of DRM formats suitable for the primary buffer, assuming a
 * buffer with the specified capabilities.
 *
 * NULL is returned if the backend doesn't have any format constraint, ie. all
 * formats are supported. An empty set is returned if the backend doesn't
 * support any format.
 */
const struct wlr_drm_format_set *wlr_output_get_primary_formats(
	struct wlr_output *output, uint32_t buffer_caps);
/**
 * Check whether direct scan-out is allowed on the output.
 *
 * Direct scan-out is typically disallowed when there are software cursors or
 * during screen capture.
 */
bool wlr_output_is_direct_scanout_allowed(struct wlr_output *output);


struct wlr_output_cursor *wlr_output_cursor_create(struct wlr_output *output);
bool wlr_output_cursor_set_buffer(struct wlr_output_cursor *cursor,
	struct wlr_buffer *buffer, int32_t hotspot_x, int32_t hotspot_y);
bool wlr_output_cursor_move(struct wlr_output_cursor *cursor,
	double x, double y);
void wlr_output_cursor_destroy(struct wlr_output_cursor *cursor);

/**
 * Initialize an output state.
 */
void wlr_output_state_init(struct wlr_output_state *state);
/**
 * Releases all resources associated with an output state.
 */
void wlr_output_state_finish(struct wlr_output_state *state);
/**
 * Enables or disables an output. A disabled output is turned off and doesn't
 * emit `frame` events.
 *
 * This state will be applied once wlr_output_commit_state() is called.
 */
void wlr_output_state_set_enabled(struct wlr_output_state *state,
	bool enabled);
/**
 * Sets the output mode of an output. An output mode will specify the resolution
 * and refresh rate, among other things.
 *
 * This state will be applied once wlr_output_commit_state() is called.
 */
void wlr_output_state_set_mode(struct wlr_output_state *state,
	struct wlr_output_mode *mode);
/**
 * Sets a custom output mode for an output. See wlr_output_state_set_mode()
 * for details.
 *
 * When the output advertises fixed modes, custom modes are not guaranteed to
 * work correctly, they may result in visual artifacts. If a suitable fixed mode
 * is available, compositors should prefer it and use wlr_output_state_set_mode()
 * instead of custom modes.
 *
 * Setting `refresh` to zero lets the backend pick a preferred value. The
 * output needs to be enabled.
 *
 * This state will be applied once wlr_output_commit_state() is called.
 */
void wlr_output_state_set_custom_mode(struct wlr_output_state *state,
	int32_t width, int32_t height, int32_t refresh);
/**
 * Sets the scale of an output. The scale is used to increase the size of UI
 * elements to aid users who use high DPI outputs.
 *
 * This state will be applied once wlr_output_commit_state() is called.
 */
void wlr_output_state_set_scale(struct wlr_output_state *state, float scale);
/**
 * Sets the transform of an output. The transform is used to rotate or flip
 * the contents of the screen.
 *
 * This state will be applied once wlr_output_commit_state() is called.
 */
void wlr_output_state_set_transform(struct wlr_output_state *state,
	enum wl_output_transform transform);
/**
 * Enables or disable adaptive sync for an output (ie. variable refresh rate).
 * Compositors can inspect `wlr_output.adaptive_sync_status` to query the
 * effective status. Backends that don't support adaptive sync will reject the
 * output commit.
 *
 * This state will be applied once wlr_output_commit_state() is called.
 */
void wlr_output_state_set_adaptive_sync_enabled(struct wlr_output_state *state,
	bool enabled);
/**
 * Sets the render format for an output.
 *
 * The default value is DRM_FORMAT_XRGB8888.
 *
 * While high bit depth render formats are necessary for a monitor to receive
 * useful high bit data, they do not guarantee it; a DRM_FORMAT_XBGR2101010
 * buffer will only lead to sending 10-bpc image data to the monitor if
 * hardware and software permit this.
 *
 * This only affects the format of the output buffer used when rendering using
 * the output's own swapchain as with wlr_output_begin_render_pass(). It has no
 * impact on the cursor buffer format, or on the formats supported for direct
 * scan-out (see also wlr_output_state_set_buffer()).
 *
 * This state will be applied once wlr_output_commit_state() is called.
 */
void wlr_output_state_set_render_format(struct wlr_output_state *state,
	uint32_t format);
/**
 * Sets the subpixel layout hint for an output. Note that this is only a hint
 * and may be ignored. The default value depends on the backend.
 *
 * This state will be applied once wlr_output_commit_state() is called.
 */
void wlr_output_state_set_subpixel(struct wlr_output_state *state,
	enum wl_output_subpixel subpixel);
/**
 * Sets the buffer for an output. The buffer contains the contents of the
 * screen. If the compositor wishes to present a new frame, they must commit
 * with a buffer.
 *
 * This state will be applied once wlr_output_commit_state() is called.
 */
void wlr_output_state_set_buffer(struct wlr_output_state *state,
	struct wlr_buffer *buffer);
/**
 * Sets the damage region for an output. This is used as a hint to the backend
 * and can be used to reduce power consumption or increase performance on some
 * devices.
 *
 * This should be called in along with wlr_output_state_set_buffer().
 * This state will be applied once wlr_output_commit_state() is called.
 */
void wlr_output_state_set_damage(struct wlr_output_state *state,
	const pixman_region32_t *damage);
/**
 * Set the output layers for an output. Output layers are used to try and take
 * advantage of backend features that may reduce the amount of things that
 * need to be composited.
 *
 * The array must be kept valid by the caller until wlr_output_state_finish()
 * and all copies of the state have been finished as well.
 * This state will be applied once wlr_output_commit_state() is called.
 */
void wlr_output_state_set_layers(struct wlr_output_state *state,
	struct wlr_output_layer_state *layers, size_t layers_len);
/**
 * Set a timeline point to wait on before displaying the next frame.
 *
 * Committing a wait timeline point without a buffer is invalid.
 *
 * There is only a single wait timeline point, waiting for multiple timeline
 * points is unsupported.
 *
 * Support for this feature is advertised by the timeline field in
 * struct wlr_output.
 */
void wlr_output_state_set_wait_timeline(struct wlr_output_state *state,
	struct wlr_drm_syncobj_timeline *timeline, uint64_t src_point);
/**
 * Set a timeline point to be signalled when the frame is no longer being used
 * by the backend.
 *
 * Committing a signal timeline point without a buffer is invalid.
 *
 * There is only a single signal timeline point, signalling multiple timeline
 * points is unsupported.
 *
 * Support for this feature is advertised by the timeline field in
 * struct wlr_output.
 */
void wlr_output_state_set_signal_timeline(struct wlr_output_state *state,
	struct wlr_drm_syncobj_timeline *timeline, uint64_t dst_point);
/**
 * Set the color transform for an output.
 *
 * The color transform is applied after blending output layers.
 */
void wlr_output_state_set_color_transform(struct wlr_output_state *state,
	struct wlr_color_transform *tr);

/**
 * Set the colorimetry image description.
 */
bool wlr_output_state_set_image_description(struct wlr_output_state *state,
	const struct wlr_output_image_description *image_desc);

/**
 * Set the color encoding and range of the primary scanout buffer.
 *
 * Pass WLR_COLOR_ENCODING_NONE / WLR_COLOR_RANGE_NONE to reset to defaults.
 */
void wlr_output_state_set_color_encoding_and_range(
	struct wlr_output_state *state,
	enum wlr_color_encoding encoding, enum wlr_color_range range);

/**
 * Copies the output state from src to dst. It is safe to then
 * wlr_output_state_finish() src and have dst still be valid.
 *
 * Note: The lifetime of the output layers inside the state are not managed. It
 * is the responsibility of the constructor of the output layers to make sure
 * they remain valid for the output state and all copies made.
 */
bool wlr_output_state_copy(struct wlr_output_state *dst,
	const struct wlr_output_state *src);


/**
 * Re-configure the swapchain as required for the output's primary buffer.
 *
 * If a NULL swapchain is passed in, a new swapchain is allocated. If the
 * swapchain is already suitable for the output's primary buffer, this function
 * is a no-op.
 *
 * The state describes the output changes the swapchain's buffers will be
 * committed with. A NULL state indicates no change.
 */
bool wlr_output_configure_primary_swapchain(struct wlr_output *output,
	const struct wlr_output_state *state, struct wlr_swapchain **swapchain);
/**
 * Begin a render pass on this output.
 *
 * Compositors can call this function to begin rendering. After the render pass
 * has been submitted, they should call wlr_output_commit_state() to submit the
 * new frame.
 *
 * On error, NULL is returned. Creating a render pass on a disabled output is
 * an error.
 *
 * The state describes the output changes the rendered frame will be
 * committed with. A NULL state indicates no change.
 *
 * If non-NULL, buffer_age is set to the drawing buffer age in number of
 * frames or -1 if unknown. This is useful for damage tracking.
 */
struct wlr_render_pass *wlr_output_begin_render_pass(struct wlr_output *output,
	struct wlr_output_state *state, struct wlr_buffer_pass_options *render_options);

#endif


/* ===== header: include/wlr/backend.h ===== */
/*
 * This an unstable interface of wlroots. No guarantees are made regarding the
 * future consistency of this API.
 */
#ifndef WLR_USE_UNSTABLE
#error "Add -DWLR_USE_UNSTABLE to enable unstable wlroots features"
#endif

#ifndef WLR_BACKEND_H
#define WLR_BACKEND_H

#include <wayland-server-core.h>

struct wlr_session;
struct wlr_backend_impl;

/**
 * Per-output state for wlr_backend_test() and wlr_backend_commit().
 */
struct wlr_backend_output_state {
	struct wlr_output *output;
	struct wlr_output_state base;
};

/**
 * A backend provides a set of input and output devices.
 *
 * Buffer capabilities and features can change over the lifetime of a backend,
 * for instance when a child backend is added to a multi-backend.
 */
struct wlr_backend {
	const struct wlr_backend_impl *impl;

	// Bitfield of supported buffer capabilities (see enum wlr_buffer_cap)
	uint32_t buffer_caps;

	struct {
		// Whether wait/signal timelines are supported in output commits
		bool timeline;
	} features;

	struct {
		/** Raised when destroyed */
		struct wl_signal destroy;
		/** Raised when new inputs are added, passed the struct wlr_input_device */
		struct wl_signal new_input;
		/** Raised when new outputs are added, passed the struct wlr_output */
		struct wl_signal new_output;
	} events;
};

/**
 * Automatically initializes the most suitable backend given the environment.
 * Will always return a multi-backend. The backend is created but not started.
 * Returns NULL on failure.
 *
 * If session_ptr is not NULL, it's populated with the session which has been
 * created with the backend, if any.
 *
 * The multi-backend will be destroyed if one of the primary underlying
 * backends is destroyed (e.g. if the primary DRM device is unplugged).
 */
struct wlr_backend *wlr_backend_autocreate(struct wl_event_loop *loop,
	struct wlr_session **session_ptr);
/**
 * Start the backend. This may signal new_input or new_output immediately, but
 * may also wait until the event loop is started. Returns false on failure.
 */
bool wlr_backend_start(struct wlr_backend *backend);
/**
 * Destroy the backend and clean up all of its resources. Normally called
 * automatically when the event loop is destroyed.
 */
void wlr_backend_destroy(struct wlr_backend *backend);
/**
 * Returns the DRM node file descriptor used by the backend's underlying
 * platform. Can be used by consumers for additional rendering operations.
 * The consumer must not close the file descriptor since the backend continues
 * to have ownership of it.
 */
int wlr_backend_get_drm_fd(struct wlr_backend *backend);

/**
 * Atomically test a new configuration for multiple outputs.
 *
 * Some backends (e.g. DRM) have global backend-wide limitations. This function
 * can be used to check whether changes across multiple outputs are supported by
 * the backend.
 */
bool wlr_backend_test(struct wlr_backend *backend,
	const struct wlr_backend_output_state *states, size_t states_len);
/**
 * Atomically apply a new configuration for multiple outputs.
 *
 * There is no guarantee that the changes will be applied atomically. Users
 * should call wlr_backend_test() first to check that the new state is supported
 * by the backend.
 */
bool wlr_backend_commit(struct wlr_backend *backend,
	const struct wlr_backend_output_state *states, size_t states_len);

#endif


