struct wlr_drm_connector_state;
struct wlr_drm_fb;
struct wlr_drm_page_flip;

// Used to provide atomic or legacy DRM functions
struct wlr_drm_interface {
	bool (*init)(struct wlr_drm_backend *drm);
	void (*finish)(struct wlr_drm_backend *drm);
	bool (*commit)(struct wlr_drm_backend *drm,
		const struct wlr_drm_device_state *state,
		struct wlr_drm_page_flip *page_flip, uint32_t flags, bool test_only);
};

extern const struct wlr_drm_interface atomic_iface;
extern const struct wlr_drm_interface legacy_iface;
extern const struct wlr_drm_interface liftoff_iface;

bool drm_legacy_crtc_set_gamma(struct wlr_drm_backend *drm,
	struct wlr_drm_crtc *crtc, size_t size, uint16_t *lut);

bool create_fb_damage_clips_blob(struct wlr_drm_backend *drm,
	int width, int height, const pixman_region32_t *damage, uint32_t *blob_id);
uint64_t to_fp16(double v);

bool drm_atomic_connector_prepare(struct wlr_drm_connector_state *state,
	bool modeset);
void drm_atomic_connector_apply_commit(struct wlr_drm_connector_state *state);
void drm_atomic_connector_rollback_commit(struct wlr_drm_connector_state *state);
bool drm_atomic_connector_set_props(drmModeAtomicReq *req,
	const struct wlr_drm_connector_state *state, bool modeset);
bool drm_atomic_crtc_set_props(drmModeAtomicReq *req,
	const struct wlr_drm_connector_state *state);

#endif


/* ===== header: include/backend/drm/properties.h ===== */
#ifndef BACKEND_DRM_PROPERTIES_H
#define BACKEND_DRM_PROPERTIES_H

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>

/*
 * These types contain the property ids for several DRM objects.
 * For more details, see:
 * https://dri.freedesktop.org/docs/drm/gpu/drm-kms.html#kms-properties
 */

struct wlr_drm_connector_props {
	uint32_t edid;
	uint32_t dpms;
	uint32_t link_status; // not guaranteed to exist
	uint32_t path;
	uint32_t vrr_capable; // not guaranteed to exist
	uint32_t subconnector; // not guaranteed to exist
	uint32_t non_desktop;
	uint32_t panel_orientation; // not guaranteed to exist
	uint32_t content_type; // not guaranteed to exist
	uint32_t max_bpc; // not guaranteed to exist

	// atomic-modesetting only

	uint32_t crtc_id;
	uint32_t colorspace;
	uint32_t hdr_output_metadata;
};

struct wlr_drm_crtc_props {
	// Neither of these are guaranteed to exist
	uint32_t vrr_enabled;
	uint32_t gamma_lut;
	uint32_t gamma_lut_size;

	// atomic-modesetting only

	uint32_t active;
	uint32_t mode_id;
	uint32_t out_fence_ptr;
};

struct wlr_drm_plane_props {
	uint32_t type;
	uint32_t rotation; // Not guaranteed to exist
	uint32_t in_formats; // Not guaranteed to exist
	uint32_t size_hints; // Not guaranteed to exist

	// atomic-modesetting only

	uint32_t src_x;
	uint32_t src_y;
	uint32_t src_w;
	uint32_t src_h;
	uint32_t crtc_x;
	uint32_t crtc_y;
	uint32_t crtc_w;
	uint32_t crtc_h;
	uint32_t fb_id;
	uint32_t crtc_id;
	uint32_t fb_damage_clips;
	uint32_t hotspot_x;
	uint32_t hotspot_y;
	uint32_t in_fence_fd;

	uint32_t color_encoding; // Not guaranteed to exist
	uint32_t color_range; // Not guaranteed to exist
};

// Equivalent to wlr_drm_color_encoding defined in the kernel (but not exported)
enum wlr_drm_color_encoding {
	WLR_DRM_COLOR_YCBCR_BT601,
	WLR_DRM_COLOR_YCBCR_BT709,
	WLR_DRM_COLOR_YCBCR_BT2020,
};

// Equivalent to wlr_drm_color_range defined in the kernel (but not exported)
enum wlr_drm_color_range {
	WLR_DRM_COLOR_YCBCR_FULL_RANGE,
	WLR_DRM_COLOR_YCBCR_LIMITED_RANGE,
};

bool get_drm_connector_props(int fd, uint32_t id,
	struct wlr_drm_connector_props *out);
bool get_drm_crtc_props(int fd, uint32_t id, struct wlr_drm_crtc_props *out);
bool get_drm_plane_props(int fd, uint32_t id, struct wlr_drm_plane_props *out);

bool get_drm_prop(int fd, uint32_t obj, uint32_t prop, uint64_t *ret);
void *get_drm_prop_blob(int fd, uint32_t obj, uint32_t prop, size_t *ret_len);
char *get_drm_prop_enum(int fd, uint32_t obj, uint32_t prop);

bool introspect_drm_prop_range(int fd, uint32_t prop_id,
	uint64_t *min, uint64_t *max);

#endif


