/* ===== header: include/util/matrix.h ===== */
#ifndef UTIL_MATRIX_H
#define UTIL_MATRIX_H

#include <wayland-server-protocol.h>

struct wlr_box;

/** Writes the identity matrix into mat */
void wlr_matrix_identity(float mat[static 9]);

/** mat ← a × b */
void wlr_matrix_multiply(float mat[static 9], const float a[static 9],
	const float b[static 9]);

/** Writes a 2D translation matrix to mat of magnitude (x, y) */
void wlr_matrix_translate(float mat[static 9], float x, float y);

/** Writes a 2D scale matrix to mat of magnitude (x, y) */
void wlr_matrix_scale(float mat[static 9], float x, float y);

/** Writes a transformation matrix which applies the specified
 *  wl_output_transform to mat */
void wlr_matrix_transform(float mat[static 9],
	enum wl_output_transform transform);

/** Shortcut for the various matrix operations involved in projecting the
 *  specified wlr_box onto a given orthographic projection with a given
 *  rotation. The result is written to mat, which can be applied to each
 *  coordinate of the box to get a new coordinate from [-1,1]. */
void wlr_matrix_project_box(float mat[static 9], const struct wlr_box *box,
	enum wl_output_transform transform, const float projection[static 9]);

/**
 * Writes a 2D orthographic projection matrix to mat of (width, height) with a
 * specified wl_output_transform.
 *
 * Equivalent to glOrtho(0, width, 0, height, 1, -1) with the transform applied.
 */
void matrix_projection(float mat[static 9], int width, int height,
	enum wl_output_transform transform);

/**
 * Compute the inverse of a matrix.
 *
 * The matrix needs to be inversible.
 */
void matrix_invert(float out[static 9], float m[static 9]);

#endif


/* ===== header: include/render/dmabuf.h ===== */
#ifndef RENDER_DMABUF_H
#define RENDER_DMABUF_H

#include <stdbool.h>
#include <stdint.h>

// Copied from <linux/dma-buf.h> to avoid #ifdef soup
#define DMA_BUF_SYNC_READ      (1 << 0)
#define DMA_BUF_SYNC_WRITE     (2 << 0)
#define DMA_BUF_SYNC_RW        (DMA_BUF_SYNC_READ | DMA_BUF_SYNC_WRITE)

/**
 * Check whether DMA-BUF import/export from/to sync_file is available.
 *
 * If this function returns true, dmabuf_import_sync_file() is supported.
 */
bool dmabuf_check_sync_file_import_export(void);

/**
 * Import a sync_file into a DMA-BUF with DMA_BUF_IOCTL_IMPORT_SYNC_FILE.
 *
 * This can be used to make explicit sync interoperate with implicit sync.
 */
bool dmabuf_import_sync_file(int dmabuf_fd, uint32_t flags, int sync_file_fd);

/**
 * Export a sync_file from a DMA-BUF with DMA_BUF_IOCTL_EXPORT_SYNC_FILE.
 *
 * The sync_file FD is returned on success, -1 is returned on error.
 *
 * This can be used to make explicit sync interoperate with implicit sync.
 */
int dmabuf_export_sync_file(int dmabuf_fd, uint32_t flags);

#endif


/* ===== header: include/render/drm_syncobj_merger.h ===== */
#ifndef WLR_RENDER_DRM_SYNCOBJ_MERGER_H
#define WLR_RENDER_DRM_SYNCOBJ_MERGER_H

#include <wayland-server-core.h>

struct wlr_buffer;

/**
 * Accumulate timeline points, to have a destination timeline point be
 * signalled when all inputs are
 */
struct wlr_drm_syncobj_merger {
	int n_ref;
	struct wlr_drm_syncobj_timeline *dst_timeline;
	uint64_t dst_point;
	int sync_fd;
};

/**
 * Create a new merger.
 *
 * The given timeline point will be signalled when all input points are
 * signalled and the merger is destroyed.
 */
struct wlr_drm_syncobj_merger *wlr_drm_syncobj_merger_create(
	struct wlr_drm_syncobj_timeline *dst_timeline, uint64_t dst_point);

struct wlr_drm_syncobj_merger *wlr_drm_syncobj_merger_ref(
	struct wlr_drm_syncobj_merger *merger);

/**
 * Target timeline point is materialized when all inputs are, and the merger is
 * destroyed.
 */
void wlr_drm_syncobj_merger_unref(struct wlr_drm_syncobj_merger *merger);
/**
 * Add a new timeline point to wait for.
 *
 * If the point is not materialized, the supplied event loop is used to schedule
 * a wait.
 */
bool wlr_drm_syncobj_merger_add(struct wlr_drm_syncobj_merger *merger,
	struct wlr_drm_syncobj_timeline *dst_timeline, uint64_t dst_point,
	struct wl_event_loop *loop);

/**
 * Add a new sync file to wait for.
 *
 * Ownership of fd is transferred to the merger.
 */
bool wlr_drm_syncobj_merger_add_sync_file(struct wlr_drm_syncobj_merger *merger,
	int fd);

/**
 * Add a new DMA-BUF release to wait for.
 *
 * Waits for write access.
 * If the platform does not support DMA-BUF<->sync file interop, the supplied
 * event_loop is used to schedule a wait.
 */
bool wlr_drm_syncobj_merger_add_dmabuf(struct wlr_drm_syncobj_merger *merger,
	struct wlr_buffer *buffer, struct wl_event_loop *event_loop);

#endif


