/**
 * @ingroup iface_wl_drm
 * @struct wl_drm_interface
 */
struct wl_drm_interface {
	/**
	 */
	void (*authenticate)(struct wl_client *client,
			     struct wl_resource *resource,
			     uint32_t id);
	/**
	 */
	void (*create_buffer)(struct wl_client *client,
			      struct wl_resource *resource,
			      uint32_t id,
			      uint32_t name,
			      int32_t width,
			      int32_t height,
			      uint32_t stride,
			      uint32_t format);
	/**
	 */
	void (*create_planar_buffer)(struct wl_client *client,
				     struct wl_resource *resource,
				     uint32_t id,
				     uint32_t name,
				     int32_t width,
				     int32_t height,
				     uint32_t format,
				     int32_t offset0,
				     int32_t stride0,
				     int32_t offset1,
				     int32_t stride1,
				     int32_t offset2,
				     int32_t stride2);
	/**
	 * @since 2
	 */
	void (*create_prime_buffer)(struct wl_client *client,
				    struct wl_resource *resource,
				    uint32_t id,
				    int32_t name,
				    int32_t width,
				    int32_t height,
				    uint32_t format,
				    int32_t offset0,
				    int32_t stride0,
				    int32_t offset1,
				    int32_t stride1,
				    int32_t offset2,
				    int32_t stride2);
};

