static void WLR_types_wlr_color_management_v1_c_resource_handle_destroy(struct wl_client *client, struct wl_resource *resource) {
	wl_resource_destroy(resource);
}

static int32_t WLR_types_wlr_color_management_v1_c_encode_cie1931_coord(float value) {
	return round(value * 1000 * 1000);
}

static float WLR_types_wlr_color_management_v1_c_decode_cie1931_coord(int32_t raw) {
	return (float)raw / (1000 * 1000);
}

static bool WLR_types_wlr_color_management_v1_c_cie1931_xy_equal(const struct wlr_color_cie1931_xy *a,
		const struct wlr_color_cie1931_xy *b) {
	return a->x == b->x && a->y == b->y;
}

static bool WLR_types_wlr_color_management_v1_c_primaries_equal(const struct wlr_color_primaries *a,
		const struct wlr_color_primaries *b) {
	return WLR_types_wlr_color_management_v1_c_cie1931_xy_equal(&a->red, &b->red) &&
		WLR_types_wlr_color_management_v1_c_cie1931_xy_equal(&a->green, &b->green) &&
		WLR_types_wlr_color_management_v1_c_cie1931_xy_equal(&a->blue, &b->blue) &&
		WLR_types_wlr_color_management_v1_c_cie1931_xy_equal(&a->white, &b->white);
}

static bool WLR_types_wlr_color_management_v1_c_img_desc_data_equal(const struct wlr_image_description_v1_data *a,
		const struct wlr_image_description_v1_data *b) {
	if (a->tf_named != b->tf_named ||
			a->primaries_named != b->primaries_named ||
			a->has_mastering_display_primaries != b->has_mastering_display_primaries ||
			a->has_mastering_luminance != b->has_mastering_luminance ||
			a->max_cll != b->max_cll ||
			a->max_fall != b->max_fall) {
		return false;
	}
	if (a->has_mastering_display_primaries &&
			!WLR_types_wlr_color_management_v1_c_primaries_equal(&a->mastering_display_primaries, &b->mastering_display_primaries)) {
		return false;
	}
	if (a->has_mastering_luminance &&
			(a->mastering_luminance.min != b->mastering_luminance.min ||
				a->mastering_luminance.max != b->mastering_luminance.max)) {
		return false;
	}
	return true;
}

static const struct wp_image_description_v1_interface WLR_types_wlr_color_management_v1_c_image_desc_impl;

static struct wlr_image_description_v1 *WLR_types_wlr_color_management_v1_c_image_desc_from_resource(struct wl_resource *resource) {
	assert(wl_resource_instance_of(resource, &wp_image_description_v1_interface, &WLR_types_wlr_color_management_v1_c_image_desc_impl));
	return wl_resource_get_user_data(resource);
}

static void WLR_types_wlr_color_management_v1_c_image_desc_handle_get_information(struct wl_client *client,
		struct wl_resource *image_desc_resource, uint32_t id) {
	struct wlr_image_description_v1 *image_desc = WLR_types_wlr_color_management_v1_c_image_desc_from_resource(image_desc_resource);
	if (image_desc == NULL) {
		wl_resource_post_error(image_desc_resource,
			WP_IMAGE_DESCRIPTION_V1_ERROR_NOT_READY,
			"image description is in failed state");
		return;
	}

	if (!image_desc->get_info_allowed) {
		wl_resource_post_error(image_desc_resource,
			WP_IMAGE_DESCRIPTION_V1_ERROR_NO_INFORMATION,
			"get_information not allowed");
		return;
	}

	uint32_t version = wl_resource_get_version(image_desc_resource);
	struct wl_resource *resource = wl_resource_create(client,
		&wp_image_description_info_v1_interface, version, id);
	if (!resource) {
		wl_client_post_no_memory(client);
		return;
	}

	struct wlr_color_primaries primaries;
	wlr_color_primaries_from_named(&primaries,
		wlr_color_manager_v1_primaries_to_wlr(image_desc->data.primaries_named));

	struct wlr_color_luminances luminances;
	wlr_color_transfer_function_get_default_luminance(
		wlr_color_manager_v1_transfer_function_to_wlr(image_desc->data.tf_named), &luminances);

	wp_image_description_info_v1_send_primaries_named(resource, image_desc->data.primaries_named);
	wp_image_description_info_v1_send_primaries(resource,
		WLR_types_wlr_color_management_v1_c_encode_cie1931_coord(primaries.red.x), WLR_types_wlr_color_management_v1_c_encode_cie1931_coord(primaries.red.y),
		WLR_types_wlr_color_management_v1_c_encode_cie1931_coord(primaries.green.x), WLR_types_wlr_color_management_v1_c_encode_cie1931_coord(primaries.green.y),
		WLR_types_wlr_color_management_v1_c_encode_cie1931_coord(primaries.blue.x), WLR_types_wlr_color_management_v1_c_encode_cie1931_coord(primaries.blue.y),
		WLR_types_wlr_color_management_v1_c_encode_cie1931_coord(primaries.white.x), WLR_types_wlr_color_management_v1_c_encode_cie1931_coord(primaries.white.y));
	wp_image_description_info_v1_send_tf_named(resource, image_desc->data.tf_named);
	wp_image_description_info_v1_send_luminances(resource,
		round(luminances.min * 10000), round(luminances.max),
		round(luminances.reference));
	// TODO: send mastering display primaries and luminances here when we add
	// support for features.set_mastering_display_primaries
	wp_image_description_info_v1_send_target_primaries(resource,
		WLR_types_wlr_color_management_v1_c_encode_cie1931_coord(primaries.red.x), WLR_types_wlr_color_management_v1_c_encode_cie1931_coord(primaries.red.y),
		WLR_types_wlr_color_management_v1_c_encode_cie1931_coord(primaries.green.x), WLR_types_wlr_color_management_v1_c_encode_cie1931_coord(primaries.green.y),
		WLR_types_wlr_color_management_v1_c_encode_cie1931_coord(primaries.blue.x), WLR_types_wlr_color_management_v1_c_encode_cie1931_coord(primaries.blue.y),
		WLR_types_wlr_color_management_v1_c_encode_cie1931_coord(primaries.white.x), WLR_types_wlr_color_management_v1_c_encode_cie1931_coord(primaries.white.y));
	wp_image_description_info_v1_send_target_luminance(resource,
		round(luminances.min * 10000), round(luminances.max));
	// TODO: send target_max_cll and target_max_fall
	wp_image_description_info_v1_send_done(resource);
	wl_resource_destroy(resource);
}

