static const struct wp_color_manager_v1_interface WLR_types_wlr_color_management_v1_c_manager_impl;

static struct wlr_color_manager_v1 *WLR_types_wlr_color_management_v1_c_manager_from_resource(struct wl_resource *resource) {
	assert(wl_resource_instance_of(resource, &wp_color_manager_v1_interface, &WLR_types_wlr_color_management_v1_c_manager_impl));
	return wl_resource_get_user_data(resource);
}

static void WLR_types_wlr_color_management_v1_c_manager_handle_get_output(struct wl_client *client,
		struct wl_resource *manager_resource, uint32_t id,
		struct wl_resource *output_resource) {
	struct wlr_color_manager_v1 *manager = WLR_types_wlr_color_management_v1_c_manager_from_resource(manager_resource);
	struct wlr_output *output = wlr_output_from_resource(output_resource);

	uint32_t version = wl_resource_get_version(manager_resource);
	struct wl_resource *cm_output_resource = wl_resource_create(client,
		&wp_color_management_output_v1_interface, version, id);
	if (!cm_output_resource) {
		wl_client_post_no_memory(client);
		return;
	}
	wl_resource_set_implementation(cm_output_resource, &WLR_types_wlr_color_management_v1_c_cm_output_impl,
		NULL, WLR_types_wlr_color_management_v1_c_cm_output_handle_resource_destroy);

	if (output == NULL) {
		return; // leave the wp_color_management_output_v1 resource inert
	}

	struct wlr_color_management_output_v1 *cm_output = calloc(1, sizeof(*cm_output));
	if (cm_output == NULL) {
		wl_client_post_no_memory(client);
		return;
	}

	cm_output->resource = cm_output_resource;
	cm_output->manager = manager;
	cm_output->output = output;

	cm_output->output_commit.notify = WLR_types_wlr_color_management_v1_c_cm_output_handle_output_commit;
	wl_signal_add(&output->events.commit, &cm_output->output_commit);

	cm_output->output_destroy.notify = WLR_types_wlr_color_management_v1_c_cm_output_handle_output_destroy;
	wl_signal_add(&output->events.destroy, &cm_output->output_destroy);

	wl_list_insert(&manager->outputs, &cm_output->link);
	wl_resource_set_user_data(cm_output->resource, cm_output);
}

static struct wlr_color_management_surface_v1 *WLR_types_wlr_color_management_v1_c_cm_surface_from_surface(struct wlr_surface *surface) {
	struct wlr_addon *addon = wlr_addon_find(&surface->addons, NULL, &WLR_types_wlr_color_management_v1_c_cm_surface_addon_impl);
	if (addon == NULL) {
		return NULL;
	}
	struct wlr_color_management_surface_v1 *cm_surface = wl_container_of(addon, cm_surface, addon);
	return cm_surface;
}

static void WLR_types_wlr_color_management_v1_c_manager_handle_get_surface(struct wl_client *client,
		struct wl_resource *manager_resource, uint32_t id,
		struct wl_resource *surface_resource) {
	struct wlr_color_manager_v1 *manager = WLR_types_wlr_color_management_v1_c_manager_from_resource(manager_resource);
	struct wlr_surface *surface = wlr_surface_from_resource(surface_resource);

	if (WLR_types_wlr_color_management_v1_c_cm_surface_from_surface(surface) != NULL) {
		wl_resource_post_error(manager_resource,
			WP_COLOR_MANAGER_V1_ERROR_SURFACE_EXISTS,
			"wp_color_management_surface_v1 already constructed for this surface");
		return;
	}

	struct wlr_color_management_surface_v1 *cm_surface = calloc(1, sizeof(*cm_surface));
	if (cm_surface == NULL) {
		wl_client_post_no_memory(client);
		return;
	}

	if (!wlr_surface_synced_init(&cm_surface->synced, surface, &WLR_types_wlr_color_management_v1_c_cm_surface_synced_impl,
			&cm_surface->pending, &cm_surface->current)) {
		wl_client_post_no_memory(client);
		free(cm_surface);
		return;
	}

	uint32_t version = wl_resource_get_version(manager_resource);
	cm_surface->resource = wl_resource_create(client,
		&wp_color_management_surface_v1_interface, version, id);
	if (!cm_surface->resource) {
		wl_client_post_no_memory(client);
		wlr_surface_synced_finish(&cm_surface->synced);
		free(cm_surface);
		return;
	}
	wl_resource_set_implementation(cm_surface->resource, &WLR_types_wlr_color_management_v1_c_cm_surface_impl, cm_surface, WLR_types_wlr_color_management_v1_c_cm_surface_handle_resource_destroy);

	cm_surface->manager = manager;
	cm_surface->surface = surface;

	wlr_addon_init(&cm_surface->addon, &surface->addons, NULL, &WLR_types_wlr_color_management_v1_c_cm_surface_addon_impl);
}

static void WLR_types_wlr_color_management_v1_c_manager_handle_get_surface_feedback(struct wl_client *client,
		struct wl_resource *manager_resource, uint32_t id,
		struct wl_resource *surface_resource) {
	struct wlr_color_manager_v1 *manager = WLR_types_wlr_color_management_v1_c_manager_from_resource(manager_resource);
	struct wlr_surface *surface = wlr_surface_from_resource(surface_resource);

	struct wlr_color_management_surface_feedback_v1 *surface_feedback =
		calloc(1, sizeof(*surface_feedback));
	if (surface_feedback == NULL) {
		wl_client_post_no_memory(client);
		return;
	}

	surface_feedback->manager = manager;

	uint32_t version = wl_resource_get_version(manager_resource);
	surface_feedback->resource = wl_resource_create(client,
		&wp_color_management_surface_feedback_v1_interface, version, id);
	if (!surface_feedback->resource) {
		wl_client_post_no_memory(client);
		free(surface_feedback);
		return;
	}
	wl_resource_set_implementation(surface_feedback->resource, &WLR_types_wlr_color_management_v1_c_surface_feedback_impl,
		surface_feedback, WLR_types_wlr_color_management_v1_c_surface_feedback_handle_resource_destroy);

	surface_feedback->surface = surface;
	surface_feedback->data = (struct wlr_image_description_v1_data){
		.tf_named = WP_COLOR_MANAGER_V1_TRANSFER_FUNCTION_GAMMA22,
		.primaries_named = WP_COLOR_MANAGER_V1_PRIMARIES_SRGB,
	};

	surface_feedback->surface_destroy.notify = WLR_types_wlr_color_management_v1_c_surface_feedback_handle_surface_destroy;
	wl_signal_add(&surface->events.destroy, &surface_feedback->surface_destroy);

	wl_list_insert(&manager->surface_feedbacks, &surface_feedback->link);
}

