static void WLR_types_wlr_xdg_foreign_v1_c_xdg_imported_handle_resource_destroy(
		struct wl_resource *resource) {
	struct wlr_xdg_imported_v1 *imported = WLR_types_wlr_xdg_foreign_v1_c_xdg_imported_from_resource(resource);
	if (!imported) {
		return;
	}

	WLR_types_wlr_xdg_foreign_v1_c_destroy_imported(imported);
}

static void WLR_types_wlr_xdg_foreign_v1_c_xdg_imported_handle_exported_destroy(struct wl_listener *listener,
		void *data) {
	struct wlr_xdg_imported_v1 *imported =
		wl_container_of(listener, imported, exported_destroyed);
	zxdg_imported_v1_send_destroyed(imported->resource);
	WLR_types_wlr_xdg_foreign_v1_c_destroy_imported(imported);
}

static void WLR_types_wlr_xdg_foreign_v1_c_xdg_importer_handle_import(struct wl_client *wl_client,
		struct wl_resource *client_resource, uint32_t id, const char *handle) {
	struct wlr_xdg_foreign_v1 *foreign =
		WLR_types_wlr_xdg_foreign_v1_c_xdg_foreign_from_importer_resource(client_resource);

	struct wlr_xdg_imported_v1 *imported = calloc(1, sizeof(*imported));
	if (imported == NULL) {
		wl_client_post_no_memory(wl_client);
		return;
	}

	imported->exported = wlr_xdg_foreign_registry_find_by_handle(
		foreign->registry, handle);
	imported->resource = wl_resource_create(wl_client, &zxdg_imported_v1_interface,
			wl_resource_get_version(client_resource), id);
	if (imported->resource == NULL) {
		wl_client_post_no_memory(wl_client);
		free(imported);
		return;
	}

	wl_resource_set_implementation(imported->resource, &WLR_types_wlr_xdg_foreign_v1_c_xdg_imported_impl,
			imported, WLR_types_wlr_xdg_foreign_v1_c_xdg_imported_handle_resource_destroy);

	if (imported->exported == NULL) {
		wl_resource_set_user_data(imported->resource, NULL);
		zxdg_imported_v1_send_destroyed(imported->resource);
		free(imported);
		return;
	}

	wl_list_init(&imported->children);
	wl_list_insert(&foreign->importer.objects, &imported->link);

	imported->exported_destroyed.notify = WLR_types_wlr_xdg_foreign_v1_c_xdg_imported_handle_exported_destroy;
	wl_signal_add(&imported->exported->events.destroy, &imported->exported_destroyed);
}

