#include <drm_fourcc.h>
#include <inttypes.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>


static void WLR_xcursor_wlr_xcursor_c_xcursor_destroy(struct wlr_xcursor *cursor) {
	for (size_t i = 0; i < cursor->image_count; i++) {
		readonly_data_buffer_drop(cursor->images[i]->readonly_buffer);
		free(cursor->images[i]->buffer);
		free(cursor->images[i]);
	}

	free(cursor->images);
	free(cursor->name);
	free(cursor);
}

static struct wlr_xcursor_image *WLR_xcursor_wlr_xcursor_c_xcursor_image_create(uint32_t width, uint32_t height,
		uint32_t hotspot_x, uint32_t hotspot_y, uint32_t delay, const void *buffer) {
	struct wlr_xcursor_image *image = calloc(1, sizeof(*image));
	if (image == NULL) {
		return NULL;
	}

	image->width = width;
	image->height = height;
	image->hotspot_x = hotspot_x;
	image->hotspot_y = hotspot_y;
	image->delay = delay;

	size_t stride = width * sizeof(uint32_t);
	size_t size = stride * height;
	image->buffer = malloc(size);
	if (image->buffer == NULL) {
		goto err_image;
	}

	memcpy(image->buffer, buffer, size);

	image->readonly_buffer = readonly_data_buffer_create(DRM_FORMAT_ARGB8888,
		stride, width, height, image->buffer);
	if (image->readonly_buffer == NULL) {
		goto err_buffer;
	}

	return image;

err_buffer:
	free(image->buffer);
err_image:
	free(image);
	return NULL;
}

static struct wlr_xcursor *WLR_xcursor_wlr_xcursor_c_xcursor_create_from_data(
		const struct cursor_metadata *metadata, struct wlr_xcursor_theme *theme) {
	struct wlr_xcursor *cursor = calloc(1, sizeof(*cursor));
	if (!cursor) {
		return NULL;
	}

	cursor->image_count = 1;
	cursor->images = calloc(1, sizeof(*cursor->images));
	if (!cursor->images) {
		goto err_free_cursor;
	}

	cursor->name = strdup(metadata->name);
	cursor->total_delay = 0;

	struct wlr_xcursor_image *image = WLR_xcursor_wlr_xcursor_c_xcursor_image_create(metadata->width, metadata->height,
		metadata->hotspot_x, metadata->hotspot_y, 0, cursor_data + metadata->offset);
	if (!image) {
		goto err_free_images;
	}

	cursor->images[0] = image;

	return cursor;

err_free_images:
	free(cursor->name);
	free(cursor->images);

err_free_cursor:
	free(cursor);
	return NULL;
}

static void WLR_xcursor_wlr_xcursor_c_load_default_theme(struct wlr_xcursor_theme *theme) {
	free(theme->name);
	theme->name = strdup("default");

	size_t cursor_count = sizeof(cursor_metadata) / sizeof(cursor_metadata[0]);
	theme->cursor_count = 0;
	theme->cursors = malloc(cursor_count * sizeof(*theme->cursors));
	if (theme->cursors == NULL) {
		return;
	}

	for (uint32_t i = 0; i < cursor_count; ++i) {
		theme->cursors[i] = WLR_xcursor_wlr_xcursor_c_xcursor_create_from_data(&cursor_metadata[i], theme);
		if (theme->cursors[i] == NULL) {
			break;
		}
		++theme->cursor_count;
	}
}

static struct wlr_xcursor *WLR_xcursor_wlr_xcursor_c_xcursor_create_from_xcursor_images(
		struct xcursor_images *images, struct wlr_xcursor_theme *theme) {
	struct wlr_xcursor *cursor = calloc(1, sizeof(*cursor));
	if (!cursor) {
		return NULL;
	}

	cursor->images = calloc(images->nimage, sizeof(cursor->images[0]));
	if (!cursor->images) {
		free(cursor);
		return NULL;
	}

	cursor->name = strdup(images->name);
	cursor->total_delay = 0;

	for (int i = 0; i < images->nimage; i++) {
		const struct xcursor_image *data = images->images[i];
		struct wlr_xcursor_image *image = WLR_xcursor_wlr_xcursor_c_xcursor_image_create(data->width, data->height,
			data->xhot, data->yhot, data->delay, data->pixels);
		if (image == NULL) {
			break;
		}

		cursor->total_delay += image->delay;
		cursor->images[i] = image;
		cursor->image_count++;
	}

	if (cursor->image_count == 0) {
		free(cursor->name);
		free(cursor->images);
		free(cursor);
		return NULL;
	}

	return cursor;
}

static struct wlr_xcursor *WLR_xcursor_wlr_xcursor_c_xcursor_theme_get_cursor(struct wlr_xcursor_theme *theme,
	const char *name);

static void WLR_xcursor_wlr_xcursor_c_load_callback(struct xcursor_images *images, void *data) {
	struct wlr_xcursor_theme *theme = data;

	if (WLR_xcursor_wlr_xcursor_c_xcursor_theme_get_cursor(theme, images->name)) {
		xcursor_images_destroy(images);
		return;
	}

	struct wlr_xcursor *cursor = WLR_xcursor_wlr_xcursor_c_xcursor_create_from_xcursor_images(images, theme);
	if (cursor) {
		theme->cursor_count++;
		struct wlr_xcursor **cursors = realloc(theme->cursors,
			theme->cursor_count * sizeof(theme->cursors[0]));
		if (cursors == NULL) {
			theme->cursor_count--;
			WLR_xcursor_wlr_xcursor_c_xcursor_destroy(cursor);
		} else {
			theme->cursors = cursors;
			theme->cursors[theme->cursor_count - 1] = cursor;
		}
	}

	xcursor_images_destroy(images);
}

struct wlr_xcursor_theme *wlr_xcursor_theme_load(const char *name, int size) {
	struct wlr_xcursor_theme *theme = calloc(1, sizeof(*theme));
	if (!theme) {
		return NULL;
	}

	if (!name) {
		name = "default";
	}

	theme->name = strdup(name);
	if (!theme->name) {
		goto out_error_name;
	}
	theme->size = size;
	theme->cursor_count = 0;
	theme->cursors = NULL;

	xcursor_load_theme(name, size, WLR_xcursor_wlr_xcursor_c_load_callback, theme);

	if (theme->cursor_count == 0) {
		WLR_xcursor_wlr_xcursor_c_load_default_theme(theme);
	}

	wlr_log(WLR_DEBUG, "Loaded cursor theme '%s' at size %d (%d available cursors)",
			theme->name, size, theme->cursor_count);

	return theme;

out_error_name:
	free(theme);
	return NULL;
}

void wlr_xcursor_theme_destroy(struct wlr_xcursor_theme *theme) {
	if (theme == NULL) {
		return;
	}

	for (unsigned int i = 0; i < theme->cursor_count; i++) {
		WLR_xcursor_wlr_xcursor_c_xcursor_destroy(theme->cursors[i]);
	}

	free(theme->name);
	free(theme->cursors);
	free(theme);
}

static struct wlr_xcursor *WLR_xcursor_wlr_xcursor_c_xcursor_theme_get_cursor(struct wlr_xcursor_theme *theme,
		const char *name) {
	for (unsigned int i = 0; i < theme->cursor_count; i++) {
		if (strcmp(name, theme->cursors[i]->name) == 0) {
			return theme->cursors[i];
		}
	}

	return NULL;
}

struct wlr_xcursor *wlr_xcursor_theme_get_cursor(struct wlr_xcursor_theme *theme,
		const char *name) {
	struct wlr_xcursor *xcursor = WLR_xcursor_wlr_xcursor_c_xcursor_theme_get_cursor(theme, name);
	if (xcursor) {
		return xcursor;
	}

	// Try the legacy name as a fallback
	const char *fallback;
	if (strcmp(name, "default") == 0) {
		fallback = "left_ptr";
	} else if (strcmp(name, "text") == 0) {
		fallback = "xterm";
	} else if (strcmp(name, "pointer") == 0) {
		fallback = "hand1";
	} else if (strcmp(name, "wait") == 0) {
		fallback = "watch";
	} else if (strcmp(name, "all-scroll") == 0) {
		fallback = "grabbing";
	} else if (strcmp(name, "sw-resize") == 0) {
		fallback = "bottom_left_corner";
	} else if (strcmp(name, "se-resize") == 0) {
		fallback = "bottom_right_corner";
	} else if (strcmp(name, "s-resize") == 0) {
		fallback = "bottom_side";
	} else if (strcmp(name, "w-resize") == 0) {
		fallback = "left_side";
	} else if (strcmp(name, "e-resize") == 0) {
		fallback = "right_side";
	} else if (strcmp(name, "nw-resize") == 0) {
		fallback = "top_left_corner";
	} else if (strcmp(name, "ne-resize") == 0) {
		fallback = "top_right_corner";
	} else if (strcmp(name, "n-resize") == 0) {
		fallback = "top_side";
	} else {
		return NULL;
	}
	return WLR_xcursor_wlr_xcursor_c_xcursor_theme_get_cursor(theme, fallback);
}

static int WLR_xcursor_wlr_xcursor_c_xcursor_frame_and_duration(struct wlr_xcursor *cursor,
		uint32_t time, uint32_t *duration) {
	if (cursor->image_count == 1) {
		if (duration) {
			*duration = 0;
		}
		return 0;
	}

	int i = 0;
	uint32_t t = time % cursor->total_delay;

	/* If there is a 0 delay in the image set then this
	 * loop breaks on it and we display that cursor until
	 * time % cursor->total_delay wraps again.
	 * Since a 0 delay is silly, and we've never actually
	 * seen one in a cursor file, we haven't bothered to
	 * "fix" this.
	 */
	while (t - cursor->images[i]->delay < t) {
		t -= cursor->images[i++]->delay;
	}

	if (!duration) {
		return i;
	}

	/* Make sure we don't accidentally tell the caller this is
	 * a static cursor image.
	 */
	if (t >= cursor->images[i]->delay) {
		*duration = 1;
	} else {
		*duration = cursor->images[i]->delay - t;
	}

	return i;
}

int wlr_xcursor_frame(struct wlr_xcursor *_cursor, uint32_t time) {
	return WLR_xcursor_wlr_xcursor_c_xcursor_frame_and_duration(_cursor, time, NULL);
}

struct wlr_buffer *wlr_xcursor_image_get_buffer(struct wlr_xcursor_image *image) {
	return &image->readonly_buffer->base;
}

const char *wlr_xcursor_get_resize_name(enum wlr_edges edges) {
	if (edges & WLR_EDGE_TOP) {
		if (edges & WLR_EDGE_RIGHT) {
			return "ne-resize";
		} else if (edges & WLR_EDGE_LEFT) {
			return "nw-resize";
		}
		return "n-resize";
	} else if (edges & WLR_EDGE_BOTTOM) {
		if (edges & WLR_EDGE_RIGHT) {
			return "se-resize";
		} else if (edges & WLR_EDGE_LEFT) {
			return "sw-resize";
		}
		return "s-resize";
	} else if (edges & WLR_EDGE_RIGHT) {
		return "e-resize";
	} else if (edges & WLR_EDGE_LEFT) {
		return "w-resize";
	}
	return "se-resize"; // fallback
}


